public CommandFailure? ProposePlan(Uuid controlId, long expectedRevision, Uuid planVersionId,
    ControlVersionView version, OperatingHolder owner, OperatingHolder? backupOwner,
    Uuid reviewerMemberId, bool reviewerHoldsWork, ControlCadence cadence,
    DateOnly effectiveFrom, string rationale, Uuid proposerMemberId, string proposerDisplay,
    DateTimeOffset proposedAt, SeparationOfDutiesWaiver? waiver)
{
    ArgumentNullException.ThrowIfNull(version);
    if (FindPlan(controlId, planVersionId) is { } existing)
        return existing.ProposerMemberId == proposerMemberId
            ? null
            : CommandFailure.StateConflict("The operating plan request was already recorded.");
    if (expectedRevision != PlanRevision(controlId))
        return CommandFailure.ForVersion(VersionedRecordRules.StaleRevision(
            "control operating plan", PlanRevision(controlId)));
    if (PendingPlan(controlId) is not null)
        return CommandFailure.StateConflict(
            "An operating plan is already pending approval for this control.");

return await executor.ExecuteAsync(new ControlOperationsLedger(request.TenantId,
        request.ProgramId),
    ledger =>
    {
        var plan = ledger.FindPlan(request.ControlId, request.PlanVersionId);
        var failure = plan is not null && plan.Status ==
            ControlOperationsLedger.PendingApproval &&
            (control.IsRetired || control.ApprovedVersion?.VersionId != plan.ControlVersionId ||
             control.ApprovedVersion.Status != ControlOperationsLedger.Approved)
                ? CommandFailure.StateConflict(
                    "The plan no longer targets the control's current approved version.")
                : ledger.ApprovePlan(request.ControlId, request.ExpectedRevision,
                    request.PlanVersionId, request.Rationale, actor.MemberId,
                    actor.Display, clock.GetUtcNow(), waiver);

/// <summary>Owns one immutable, period-aware assertion linking an artifact to an exact source revision.</summary>
public sealed class EvidenceSupport : Aggregate
{
    const int MaximumTextLength = 2000;
    static readonly HashSet<string> SupportedTypes = new(StringComparer.Ordinal)
    {
        "control", "control_version", "control_occurrence", "control_evaluation", "period"
    };

    readonly Uuid _tenantId;
    readonly Uuid _programId;

    public EvidenceSupportLinked? Current { get; private set; }
    public long Revision => Current?.Revision ?? 0;

    public EvidenceSupport(Uuid tenantId, Uuid programId, Uuid supportId)
        : base(supportId, new EventStreamAddress(tenantId.ToString(), "evidence-support",
            supportId.ToString()))
    {
        _tenantId = tenantId;
        _programId = programId;
        On<EvidenceSupportLinked>(Apply);
    }

    /// <summary>Derives a stable relationship identity from the exact artifact, target and covered period.</summary>
    public static Uuid IdFor(LinkEvidenceSupport request)
    {
        ArgumentNullException.ThrowIfNull(request);
        var recordType = NormalizeType(request.SupportedRecordType);
        var identity = string.Join('\n', "evidence-support-v1", request.ProgramId,
            request.ArtifactId, recordType, request.SupportedRecordId,
            request.SupportedRecordRevision.ToString(CultureInfo.InvariantCulture),
            request.PeriodStart.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture),
            request.PeriodEnd.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture));
        return Uuid.CreateVersion5(request.TenantId, identity);

public CommandFailure? RecordAttestPackageDelivery(long expectedRevision, Uuid packageId,
    string decision, string rationale, string? recipient, string? deliveryReference,
    Uuid actorMemberId, string actorDisplay, DateTimeOffset recordedAt)
{
    if (_current is not { } current)
        return CommandFailure.MissingRecord("The client export was not found.");
    decision = Clean(decision).ToLowerInvariant();
    rationale = Clean(rationale);
    recipient = Clean(recipient);
    deliveryReference = Clean(deliveryReference);
    var required = current.Content.RequiredAttestPackages.FirstOrDefault(item => item.PackageId == packageId);
    if (required is null)
        return CommandFailure.MissingRecord("The attest collaboration package was not required by this export.");
    var prior = current.AttestPackageDeliveries.LastOrDefault(item => item.PackageId == packageId);
    if (prior is not null && prior.Decision == decision && prior.Rationale == rationale && prior.Recipient == NullIfEmpty(recipient) &&
            prior.DeliveryReference == NullIfEmpty(deliveryReference) && prior.RecordedByMemberId == actorMemberId &&
            prior.RecordedByDisplay == Clean(actorDisplay) && prior.RecordedAt == recordedAt
            )
        return null;
    if (prior?.Decision == "delivered")
        return CommandFailure.StateConflict("A successful attest-package delivery decision is immutable.");
    if (expectedRevision != Revision)
        return StaleRevision();
    if (current.Status != "built" || decision is not ("delivered" or "not_delivered") ||
        current.AttestPackageDeliveries.Count(item => item.PackageId == packageId) >= MaximumAttestDeliveryAttempts ||
        !Bounded(rationale, 1, MaximumTextLength) || !ValidActor(actorMemberId, actorDisplay, recordedAt) ||
        recordedAt < current.UpdatedAt ||
        decision == "delivered" && (!Bounded(recipient, 1, 300) || !Bounded(deliveryReference, 1, 500)))
        return CommandFailure.StateConflict("An attest package delivery decision requires a successfully built export and retained receipt or rationale.");
    var delivery = new ClientExportAttestDeliveryView(required.EngagementId, required.PackageId,
        required.ManifestSha256, decision, rationale, NullIfEmpty(recipient),
        NullIfEmpty(deliveryReference), actorMemberId, actorDisplay.Trim(), recordedAt);
    var state = current with
    {
        Revision = Revision + 1,
        AttestPackageDeliveries = Append(current.AttestPackageDeliveries, delivery),
        ActorMemberId = actorMemberId,
        ActorDisplay = actorDisplay.Trim(),
        UpdatedAt = recordedAt,
    };
    return Emit(state, actorMemberId, recordedAt,
        static (tenant, subject, revision, actor, snapshot, at) =>
